// Generates lib/core/ai/bearoff_data.dart: the exact one-sided bear-off
// table (expected rolls with perfect play for every home position).
//   dart run tool/gen_bearoff.dart
import 'dart:io';

import 'package:haftnard/core/ai/bearoff.dart';

void main() {
  final sw = Stopwatch()..start();
  final e = BearOff.compute();
  final data = BearOff.encode(e);
  File('lib/core/ai/bearoff_data.dart').writeAsStringSync('''
// GENERATED by tool/gen_bearoff.dart — do not edit.
// Exact one-sided bear-off table (${BearOff.size} positions, Uint16 rolls ×
// ${BearOff.scale.toInt()}), base64.
const String kBearOffData =
    '$data';
''');
  stdout.writeln(
    'bear-off table: ${BearOff.size} positions in ${sw.elapsedMilliseconds} ms; '
    '15 on the 6-point: ${e[BearOff.index([0, 0, 0, 0, 0, 0, 15])].toStringAsFixed(3)} rolls',
  );
}
